import os


class LoggerConfiguration(object):
    """LoggerConfiguration class."""

    def __init__(self):
        """LoggerConfiguration init method."""

        self._config = {'LOGGER': {}}
        self.default_configuration = {
            'MODE': 'write',
            'PATH': self._get_default_log_path(),
            'RAW_LOG': True,
            'DEBUG_LEVEL': 'DEBUG',  # TRACE|DEBUG|INFO
            'DATE_FORMAT': '%d %H:%M:%S'
        }

    def get_logger_config(self):
        """
        Return logger config.

        :return: logger config.
        """
        return self._config

    def set_logger_params(self, logger_params=None):
        params = self.default_configuration.copy()
        if logger_params:
            params.update(logger_params)
        self._config['LOGGER'].update(params)

    @staticmethod
    def _get_default_log_path():

        log_path = "."
        if 'LOG_DIR' in os.environ:
            log_path = os.environ['LOG_DIR']

        return log_path
